-- Этап 4: планирование и общие реестры для атомарного подтверждения готовки.
create table public.kitchen_modules(version integer primary key);
insert into public.kitchen_modules values(4);
create table public.storage_places(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),name text not null check(length(trim(name)) between 1 and 100),unique(family_id,name));
create function public.kitchen_default_places() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.storage_places(family_id,name) values(new.id,'Холодильник'),(new.id,'Морозилка'),(new.id,'Кухонный шкаф'),(new.id,'Кладовая');return new;end$$;
create trigger kitchen_places_after_family after insert on public.families for each row execute function public.kitchen_default_places();
insert into public.storage_places(family_id,name) select f.id,p.name from public.families f cross join (values('Холодильник'),('Морозилка'),('Кухонный шкаф'),('Кладовая'))p(name) on conflict do nothing;
create function public.product_key(p text) returns text language sql immutable set search_path='' as $$select lower(regexp_replace(trim(p),'\s+',' ','g'))$$;
create function public.base_unit(p text) returns text language sql immutable set search_path='' as $$select case p when 'кг' then 'г' when 'л' then 'мл' else p end$$;
create function public.unit_factor(p text) returns numeric language sql immutable set search_path='' as $$select case when p in ('кг','л') then 1000::numeric else 1::numeric end$$;
create function public.kitchen_number(p text) returns numeric language plpgsql immutable set search_path='' as $$declare n numeric;begin if p is null or p !~ '^[0-9]+([.,][0-9]{1,4})?$' then raise exception 'Укажите неотрицательное число, до 4 знаков после запятой';end if;n:=replace(p,',','.')::numeric;if n>1000000000 then raise exception 'Значение слишком большое';end if;return n;end$$;
create table public.products(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),name text not null check(length(trim(name)) between 1 and 200),name_key text not null,category text not null default 'Другое',minimum numeric(18,4) not null default 0 check(minimum>=0),unit text not null default 'шт.',version integer not null default 1,archived boolean not null default false,unique(family_id,name_key));
create table public.stock_batches(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),product_id uuid not null references public.products(id),quantity numeric(18,4) not null check(quantity>=0),unit text not null check(unit in ('г','мл','шт.','ч. л.','ст. л.','стакан','упаковка','порц.')),purchased_on date not null default (timezone('Asia/Yekaterinburg',now())::date),expires_on date,place_id uuid references public.storage_places(id),notes text not null default '',version integer not null default 1,created_at timestamptz not null default now());
create table public.stock_movements(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),batch_id uuid not null references public.stock_batches(id),quantity numeric(18,4) not null,reason text not null,operation_id uuid not null,created_at timestamptz not null default now());
create table public.menu_items(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),recipe_id uuid not null references public.recipes(id),title text not null,recipe_snapshot jsonb not null default '{}',month date not null,date date,meal text not null check(meal in ('Завтрак','Обед','Ужин','Перекус','Другое')),servings numeric(12,4) not null check(servings>0 and servings<=1000),planned_count integer not null default 1 check(planned_count between 1 and 100),status text not null default 'Запланировано' check(status in ('Запланировано','В процессе','Приготовлено','Сделана заготовка','Приготовлено из заготовки','Перенесено','Отменено')),notes text not null default '',version integer not null default 1,created_at timestamptz not null default now(),check(month=date_trunc('month',month)::date),check(date is null or date_trunc('month',date)::date=month));
create table public.cooking_tasks(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),recipe_id uuid not null references public.recipes(id),menu_id uuid references public.menu_items(id),title text not null,recipe_snapshot jsonb not null default '{}',date date not null,servings numeric(12,4) not null check(servings>0 and servings<=1000),planned_preparations numeric(12,4) not null default 0 check(planned_preparations>=0),place_id uuid references public.storage_places(id),notes text not null default '',checked_steps jsonb not null default '[]',status text not null default 'Запланировано' check(status in ('Запланировано','В процессе','Приготовлено','Отменено')),version integer not null default 1,created_at timestamptz not null default now());
create table public.cooking_events(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),recipe_id uuid not null references public.recipes(id),menu_id uuid references public.menu_items(id),task_id uuid unique references public.cooking_tasks(id),servings numeric(12,4) not null check(servings>0),eaten numeric(12,4) not null check(eaten>=0),fridge numeric(12,4) not null check(fridge>=0),frozen numeric(12,4) not null check(frozen>=0),recipe_snapshot jsonb not null,usage jsonb not null,notes text not null default '',cooked_on date not null,created_at timestamptz not null default now(),check(servings=eaten+fridge+frozen));
create table public.preparations(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),recipe_id uuid references public.recipes(id),event_id uuid references public.cooking_events(id),title text not null,photo_path text not null default '',category text not null default 'Готовые блюда',quantity numeric(18,4) not null check(quantity>=0),unit text not null default 'порц.',prepared_on date not null,expires_on date,storage_recommendation text not null default '',place_id uuid references public.storage_places(id),notes text not null default '',version integer not null default 1,created_at timestamptz not null default now());
create table public.preparation_movements(id uuid primary key default gen_random_uuid(),family_id uuid not null references public.families(id),preparation_id uuid not null references public.preparations(id),quantity numeric(18,4) not null,reason text not null,operation_id uuid not null,created_at timestamptz not null default now());
create table public.kitchen_operations(id uuid not null,family_id uuid not null references public.families(id),action text not null,payload_hash text not null,result jsonb not null,actor_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),primary key(family_id,id));
-- Все реестры читаются только своей семьёй, запись — только через проверенные RPC.
do $$declare t text;begin foreach t in array array['storage_places','products','stock_batches','stock_movements','menu_items','cooking_tasks','cooking_events','preparations','preparation_movements','kitchen_operations'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy family_read on public.%I for select to authenticated using(public.is_family_member(family_id))',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('create index %I on public.%I(family_id)',t||'_family_idx',t);end loop;end$$;
alter table public.kitchen_modules enable row level security;create policy modules_read on public.kitchen_modules for select to authenticated using(true);grant select on public.kitchen_modules to authenticated;
create index stock_batches_fefo_idx on public.stock_batches(family_id,product_id,unit,expires_on) where quantity>0;
create index menu_items_dates_idx on public.menu_items(family_id,month,date);
create index kitchen_events_dates_idx on public.cooking_events(family_id,cooked_on);
create function public._recipe_snapshot(p_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$select to_jsonb(r)||jsonb_build_object('ingredients',coalesce((select jsonb_agg(to_jsonb(i) order by position) from public.recipe_ingredients i where recipe_id=r.id),'[]'::jsonb),'steps',coalesce((select jsonb_agg(to_jsonb(s) order by position) from public.recipe_steps s where recipe_id=r.id),'[]'::jsonb)) from public.recipes r where id=p_id$$;
revoke all on function public._recipe_snapshot(uuid) from public,anon,authenticated;
create function public._planning_action(f uuid,k uuid,a text,d jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare rid uuid;eid uuid;v integer;old public.menu_items;task public.cooking_tasks;r public.recipes;qty numeric;eaten numeric;fridge numeric;frozen numeric;usage jsonb;u jsonb;needed numeric;available numeric;b record;take numeric;pid uuid;pl uuid;tid uuid;mid uuid;prepared uuid;repeat_n integer;begin
 if a='menu_save' then
  rid:=coalesce((d->>'id')::uuid,gen_random_uuid());select * into old from public.menu_items where id=rid;
  if found and (old.family_id<>f or old.version is distinct from (d->>'version')::integer) then raise exception 'План изменён на другом устройстве. Обновите данные';end if;
  select * into r from public.recipes where id=(d->>'recipe_id')::uuid and family_id=f and (deleted_at is null or id=old.recipe_id);if not found then raise exception 'Рецепт недоступен';end if;
  if d->>'status' not in ('Запланировано','В процессе','Перенесено','Отменено') then raise exception 'Приготовление подтверждается отдельной операцией';end if;
  if old.id is not null and exists(select 1 from public.cooking_events where menu_id=rid) and (r.id<>old.recipe_id or (d->>'servings')::numeric<>old.servings) then raise exception 'Нельзя менять рецепт и порции плана с историей; создайте новое приготовление';end if;
  insert into public.menu_items(id,family_id,recipe_id,title,month,date,meal,servings,planned_count,status,notes)
  values(rid,f,r.id,r.title,(d->>'month')::date,nullif(d->>'date','')::date,d->>'meal',public.kitchen_number(d->>'servings'),(d->>'planned_count')::integer,d->>'status',coalesce(d->>'notes',''))
  on conflict(id) do update set month=excluded.month,date=excluded.date,meal=excluded.meal,servings=excluded.servings,planned_count=excluded.planned_count,status=excluded.status,notes=excluded.notes,recipe_id=excluded.recipe_id,title=excluded.title,version=public.menu_items.version+1;
  update public.menu_items set recipe_snapshot=case when old.id is not null and old.recipe_id=r.id then old.recipe_snapshot else public._recipe_snapshot(r.id) end where id=rid;return jsonb_build_object('id',rid);
 elsif a='menu_repeat' then
  select * into old from public.menu_items where id=(d->>'id')::uuid and family_id=f;if not found or old.version is distinct from (d->>'version')::integer then raise exception 'Обновите план';end if;
  repeat_n:=(d->>'count')::integer;if repeat_n not between 1 and 31 then raise exception 'Количество повторов — от 1 до 31';end if;
  if (d->>'interval')::integer not between 1 and 365 then raise exception 'Интервал — от 1 до 365 дней';end if;for v in 1..repeat_n loop insert into public.menu_items(family_id,recipe_id,title,month,date,meal,servings,status,notes) values(f,old.recipe_id,old.title,date_trunc('month',coalesce(old.date,old.month)+v*((d->>'interval')::integer))::date,coalesce(old.date,old.month)+v*((d->>'interval')::integer),old.meal,old.servings,'Запланировано',old.notes);end loop;update public.menu_items set recipe_snapshot=old.recipe_snapshot where family_id=f and recipe_id=old.recipe_id and recipe_snapshot='{}';return jsonb_build_object('count',repeat_n);
 elsif a='task_save' then
  rid:=coalesce((d->>'id')::uuid,gen_random_uuid());select * into task from public.cooking_tasks where id=rid;
  if found and (task.family_id<>f or task.version is distinct from (d->>'version')::integer or task.status='Приготовлено') then raise exception 'Задача изменена или уже приготовлена';end if;
  select * into r from public.recipes where id=(d->>'recipe_id')::uuid and family_id=f and (deleted_at is null or id=task.recipe_id);if not found then raise exception 'Рецепт недоступен';end if;
  mid:=nullif(d->>'menu_id','')::uuid;if mid is not null and not exists(select 1 from public.menu_items where id=mid and family_id=f and recipe_id=r.id and status<>'Отменено') then raise exception 'Пункт меню недоступен';end if;
  pl:=nullif(d->>'place_id','')::uuid;if pl is not null and not exists(select 1 from public.storage_places where id=pl and family_id=f) then raise exception 'Место хранения недоступно';end if;
  if d->>'status' not in ('Запланировано','В процессе','Отменено') then raise exception 'Используйте подтверждение приготовления';end if;
  insert into public.cooking_tasks(id,family_id,recipe_id,menu_id,title,date,servings,planned_preparations,place_id,notes,status,checked_steps) values(rid,f,r.id,mid,r.title,(d->>'date')::date,public.kitchen_number(d->>'servings'),public.kitchen_number(coalesce(d->>'planned_preparations','0')),pl,coalesce(d->>'notes',''),d->>'status',coalesce(d->'checked_steps','[]'::jsonb)) on conflict(id) do update set date=excluded.date,servings=excluded.servings,planned_preparations=excluded.planned_preparations,place_id=excluded.place_id,notes=excluded.notes,status=excluded.status,checked_steps=excluded.checked_steps,recipe_id=excluded.recipe_id,menu_id=excluded.menu_id,title=excluded.title,version=public.cooking_tasks.version+1;update public.cooking_tasks set recipe_snapshot=case when task.id is not null and task.recipe_id=r.id then task.recipe_snapshot else public._recipe_snapshot(r.id) end where id=rid;return jsonb_build_object('id',rid);
 elsif a='cook_confirm' then
  tid:=nullif(d->>'task_id','')::uuid;mid:=nullif(d->>'menu_id','')::uuid;
  if tid is not null then select * into task from public.cooking_tasks where id=tid and family_id=f;if not found or task.status in ('Приготовлено','Отменено') or task.version is distinct from (d->>'version')::integer then raise exception 'Задача изменена или уже подтверждена';end if;mid:=task.menu_id;rid:=task.recipe_id;else select * into old from public.menu_items where id=mid and family_id=f;if not found or old.version is distinct from (d->>'version')::integer or old.status in ('Отменено','Приготовлено','Сделана заготовка','Приготовлено из заготовки') then raise exception 'Обновите пункт меню';end if;rid:=old.recipe_id;end if;
  if mid is not null and (select count(*) from public.cooking_events where menu_id=mid)>=(select planned_count from public.menu_items where id=mid) then raise exception 'Все приготовления этого пункта уже подтверждены';end if;
  select * into r from public.recipes where id=rid and family_id=f;
  qty:=public.kitchen_number(d->>'servings');eaten:=public.kitchen_number(d->>'eaten');fridge:=public.kitchen_number(d->>'fridge');frozen:=public.kitchen_number(d->>'frozen');if qty<=0 or qty<>eaten+fridge+frozen then raise exception 'Сумма съеденного, охлаждённого и замороженного должна равняться фактическим порциям';end if;
  usage:=d->'usage';if jsonb_typeof(usage) is distinct from 'array' or coalesce((d->>'usage_confirmed')::boolean,false)=false then raise exception 'Подтвердите фактический расход ингредиентов';end if;
  -- Одинаковые точные названия объединяются только с совместимой единицей.
  for u in select jsonb_build_object('key',public.product_key(x->>'name'),'unit',public.base_unit(x->>'unit'),'amount',sum(public.kitchen_number(x->>'amount')*public.unit_factor(x->>'unit'))) from jsonb_array_elements(usage)x group by public.product_key(x->>'name'),public.base_unit(x->>'unit') loop
   needed:=(u->>'amount')::numeric;if needed=0 then continue;end if;
   select id into pid from public.products where family_id=f and name_key=u->>'key' and not archived;
   select coalesce(sum(quantity),0) into available from public.stock_batches where family_id=f and product_id=pid and unit=u->>'unit' and (expires_on is null or expires_on>=timezone('Asia/Yekaterinburg',now())::date);
   if available<needed then raise exception 'Недостаточно продукта «%»: есть %, нужно % %',u->>'key',available,needed,u->>'unit';end if;
   for b in select * from public.stock_batches where family_id=f and product_id=pid and unit=u->>'unit' and quantity>0 and (expires_on is null or expires_on>=timezone('Asia/Yekaterinburg',now())::date) order by expires_on nulls last,purchased_on,id for update loop take:=least(needed,b.quantity);update public.stock_batches set quantity=quantity-take,version=version+1 where id=b.id;insert into public.stock_movements(family_id,batch_id,quantity,reason,operation_id) values(f,b.id,-take,'Приготовление',k);needed:=needed-take;exit when needed=0;end loop;
  end loop;
  eid:=gen_random_uuid();insert into public.cooking_events(id,family_id,recipe_id,menu_id,task_id,servings,eaten,fridge,frozen,recipe_snapshot,usage,notes,cooked_on) values(eid,f,r.id,mid,tid,qty,eaten,fridge,frozen,case when tid is not null then task.recipe_snapshot else old.recipe_snapshot end,usage,coalesce(d->>'notes',''),(d->>'date')::date);
  for v in 1..2 loop take:=case v when 1 then fridge else frozen end;if take=0 then continue;end if;select id into pl from public.storage_places where family_id=f and name=case v when 1 then 'Холодильник' else 'Морозилка' end;prepared:=gen_random_uuid();insert into public.preparations(id,family_id,recipe_id,event_id,title,photo_path,quantity,prepared_on,expires_on,storage_recommendation,place_id) values(prepared,f,r.id,eid,r.title,r.cover_path,take,(d->>'date')::date,nullif(d->>case v when 1 then 'fridge_expiry' else 'frozen_expiry' end,'')::date,r.shelf_life,pl);insert into public.preparation_movements(family_id,preparation_id,quantity,reason,operation_id)values(f,prepared,take,'Приготовлено',k);end loop;
  if tid is not null then update public.cooking_tasks set status='Приготовлено',version=version+1 where id=tid;end if;
  if mid is not null then update public.menu_items set status=case when (select count(*) from public.cooking_events where menu_id=mid)>=planned_count then case when frozen>0 or fridge>0 then 'Сделана заготовка' else 'Приготовлено' end else 'Запланировано' end,version=version+1 where id=mid;end if;
  return jsonb_build_object('id',eid);
 end if;raise exception 'Неизвестное действие планирования';end$$;
create function public.kitchen_mutate(p_family uuid,p_key uuid,p_action text,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare previous public.kitchen_operations;result jsonb;begin
 perform 1 from public.families where id=p_family for update;
 if not public.can_edit_family(p_family) then raise exception 'Нет права изменять данные этой семьи';end if;
 if p_key is null or p_data is null or jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>2000000 then raise exception 'Некорректная операция';end if;
 select * into previous from public.kitchen_operations where family_id=p_family and id=p_key;
 if found then if previous.action<>p_action or previous.payload_hash<>md5(p_data::text) then raise exception 'Этот идентификатор уже использован для другой операции';end if;return previous.result;end if;
 if p_action in ('menu_save','menu_repeat','task_save','cook_confirm') then result:=public._planning_action(p_family,p_key,p_action,p_data);
 elsif p_action in ('product_save','batch_save','prep_save','prep_use','place_save') and to_regprocedure('public._inventory_action(uuid,uuid,text,jsonb)') is not null then execute 'select public._inventory_action($1,$2,$3,$4)' into result using p_family,p_key,p_action,p_data;
 elsif p_action in ('shopping_save','shopping_generate','purchase_confirm','purchase_reverse','expense_save','budget_save') and to_regprocedure('public._finance_action(uuid,uuid,text,jsonb)') is not null then execute 'select public._finance_action($1,$2,$3,$4)' into result using p_family,p_key,p_action,p_data;
 else raise exception 'Действие недоступно. Проверьте применение миграций';end if;
 insert into public.kitchen_operations(id,family_id,action,payload_hash,result,actor_id)values(p_key,p_family,p_action,md5(p_data::text),result,auth.uid());return result;end$$;
create function public.kitchen_rows(t text,f uuid,o integer) returns jsonb language plpgsql stable security invoker set search_path='' as $$declare result jsonb;begin
 if t not in ('storage_places','products','stock_batches','stock_movements','menu_items','cooking_tasks','cooking_events','preparations','preparation_movements','kitchen_operations','shopping_items','purchases','expenses','financial_movements','monthly_budgets') then raise exception 'Неизвестный реестр';end if;
 if to_regclass('public.'||t) is null then return '[]';end if;execute format('select coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) from (select * from public.%I where family_id=$1 order by id limit 200 offset $2)x',t) into result using f,greatest(o,0);return result;end$$;
create function public.get_kitchen_state(p_family uuid,p_from date,p_to date,p_offset integer default 0) returns jsonb language plpgsql stable security invoker set search_path='' as $$declare t text;result jsonb;summary jsonb;begin
 if not public.is_family_member(p_family) then raise exception 'Семейное пространство недоступно';end if;
 result:=jsonb_build_object('schema_version',(select max(version) from public.kitchen_modules));
 foreach t in array array['storage_places','products','stock_batches','stock_movements','menu_items','cooking_tasks','cooking_events','preparations','preparation_movements','kitchen_operations','shopping_items','purchases','expenses','financial_movements','monthly_budgets'] loop result:=result||jsonb_build_object(t,public.kitchen_rows(t,p_family,p_offset));end loop;
 if to_regprocedure('public.kitchen_finance_summary(uuid,date,date)') is not null then execute 'select public.kitchen_finance_summary($1,$2,$3)' into summary using p_family,p_from,p_to;result:=result||jsonb_build_object('summary',summary);end if;
 return result;end$$;
revoke all on function public.kitchen_default_places(),public._planning_action(uuid,uuid,text,jsonb) from public,anon,authenticated;
revoke all on function public.product_key(text),public.base_unit(text),public.unit_factor(text),public.kitchen_number(text),public.kitchen_mutate(uuid,uuid,text,jsonb),public.kitchen_rows(text,uuid,integer),public.get_kitchen_state(uuid,date,date,integer) from public,anon;
grant execute on function public.product_key(text),public.base_unit(text),public.unit_factor(text),public.kitchen_number(text),public.kitchen_mutate(uuid,uuid,text,jsonb),public.kitchen_rows(text,uuid,integer),public.get_kitchen_state(uuid,date,date,integer) to authenticated;
do $$declare t text;begin if exists(select 1 from pg_publication where pubname='supabase_realtime')then foreach t in array array['menu_items','cooking_tasks','cooking_events','stock_batches','preparations','kitchen_operations']loop execute format('alter publication supabase_realtime add table public.%I',t);end loop;end if;end$$;

create function public.kitchen_photo_referenced(p_path text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.menu_items where position(p_path in recipe_snapshot::text)>0) or exists(select 1 from public.cooking_tasks where position(p_path in recipe_snapshot::text)>0) or exists(select 1 from public.cooking_events where position(p_path in recipe_snapshot::text)>0) or exists(select 1 from public.preparations where photo_path=p_path)$$;
revoke all on function public.kitchen_photo_referenced(text) from public,anon;grant execute on function public.kitchen_photo_referenced(text) to authenticated;
create policy kitchen_history_photo_protection on storage.objects as restrictive for delete to authenticated using(bucket_id<>'recipe-photos' or not public.kitchen_photo_referenced(name));
